    "type": "git",
    "url": "https://tangled.org/danabra.mov/woodshed"
  },
  "type": "module",
  "bin": {
    "woodshed": "./dist/cli.js"
  },
  "files": [
    "dist"
  ],
  "keywords": [
    "claude-skills"
  ],
  "scripts": {
    "build": "tsc",
    "prepublishOnly": "npm run build",
    "run:example": "cd example && node ../dist/cli.js",
    "run:test": "cd test/root && node ../../dist/cli.js",
    "test": "vitest run",
    "test:watch": "vitest",
    "format": "prettier --write .",
    "format:check": "prettier --check .",
    "prepare": "husky"
  },
  "dependencies": {
    "@inquirer/prompts": "^8.2.0",
    "ink": "^5.0.1",
    "react": "^18.3.1"
  },
  "devDependencies": {
    "@types/node": "^22.10.2",
    "@types/react": "^18.3.12",
    "husky": "^9.1.7",
    "lint-staged": "^16.2.7",
    "prettier": "^3.7.4",
    "typescript": "^5.7.2",
    "vitest": "^4.0.17"
  },
  "lint-staged": {
    "*": "prettier --write --ignore-unknown"
  }
}

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    include: ["test/**/*.test.ts"],
    testTimeout: 30000,
  },
});

